const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2013,"grade":"5-6","contest":"Золотое руно","letters":"ABC","count":60,"language":"kk","points":3,"tasksFile":"ZR_1213_KZ_5-6.pdf","answersFile":"reviewed-5-6-vkz.pdf","title":"Pax Germanica. Единство немецкой стихии","sourceFile":"sources/golden-fleece/2013/interactive-5-6-vkz.json","sections":[{"start":1,"title":"Тарих"},{"start":16,"title":"Әдебиет"},{"start":31,"title":"Күнделікті мәдениет"},{"start":46,"title":"Көркем мәдениет"}],"variant":"kz","editionSuffix":"vkz","editionLabel":"На казахском языке","reviewedKey":true}, [{"number":1,"question":"Рим әскерлері герман тайпаларымен соғыста алғашқы үлкен жеңіске қай қолбасшының басшылығымен жетті деп есептелінеді?","choices":["Гай Марий","Октавиан Август","Гай Юлий Цезарь"],"answer":0,"title":"Римляне против племён","steps":["В конце II века до нашей эры римский полководец разгромил тевтонов и кимвров. В Риме его считали защитником от вторжения.","Этим полководцем был Гай Марий."]},{"number":2,"question":"Пруссия мемлекетінің милитаристік рухын жария ету үшін күнделікті өмірде де әскери киіммен жүрген король кім?","choices":["ҮІ Карл","ІІ Фридрих","І Фридрих-Вильгельм"],"answer":2,"title":"Король в мундире","steps":["Прусский правитель постоянно заботился об армии и разводе караулов. Его так и прозвали королём-солдатом.","Это Фридрих Вильгельм I, отец Фридриха Великого."]},{"number":3,"question":"Қасиетті Рим империясының императоры І Фридрих Барбаросса қандай әулеттің өкілі болды?","choices":["Габсбургтер","Гогенштауфендер","Каролингтер"],"answer":1,"title":"Род Барбароссы","steps":["В XII веке империей правил дом, связанный со швабским замком Гогенштауфен. Один из его правителей носил прозвище Рыжебородый.","Фридрих Барбаросса принадлежал к Гогенштауфенам."]},{"number":4,"question":"Қазіргі Германия жерінің түп бейнесі – мемлекеттің шекарасы алғаш рет қандай құжатта көрсетілді?","choices":["«Алтын булла»","Верден шарты","Вормск конкордаты"],"answer":1,"title":"Границы державы","steps":["Внуки Карла Великого заключили соглашение о разделении империи. Людовик получил восточные земли.","Границы определил Верденский договор 843 года."]},{"number":5,"question":"Қасиетті Рим империясының тұңғыш императоры І Оттон 955 жылы жасаған қандай іс-әрекетімен белгілі?","choices":["Италияға басып кірді","Германияның королі атанды","Венгрлермен соғыста тарихи жеңіске жетті"],"answer":2,"title":"Сражение 955 года","steps":["На реке Лех германский правитель объединил силы против венгерских всадников. Победа остановила венгерские набеги на запад.","Победителем в битве на Лехе стал Оттон I."]},{"number":6,"question":"1710 жылы саксондардың қаласы Мейссенде ашылған Еуропадағы тұңғыш мануфактура не өндірді?","choices":["Фарфор","Фейерверк","Жібек мата"],"answer":0,"title":"Мануфактура в Мейсене","steps":["В Саксонии научились производить твёрдую белую керамику, похожую на привозные азиатские изделия. При Августе Сильном открыли мануфактуру.","В Мейсене начали производить фарфор."]},{"number":7,"question":"1787 жылы Австрия императоры қабылдаған Қылмыстық кодексте, замандастарын таң қалдырып, қылмыстар қатарынан алынып тасталған қандай жағдай?","choices":["Бал ашу мен сиқыр жасау","Құпия қоғамдардың қатарында болу","Әскердегі қызметінен жалтару"],"answer":0,"title":"Просвещённый кодекс","steps":["Кодекс Иосифа II описывал наказуемые поступки без обращения к сверхъестественному вреду.","Ведовство и колдовство перестали считаться преступлениями сами по себе."]},{"number":8,"question":"ХІХ ғасырдағы немістің көрнекті мемлекеттік қайраткері О.фон Бисмарк қай мемлекетте елші болды?","choices":["Испания","Англия","Ресей"],"answer":2,"title":"Посольство Бисмарка","steps":["Перед тем как возглавить прусское правительство, Бисмарк работал послом в Санкт-Петербурге.","Санкт-Петербург был столицей Российской империи."]},{"number":9,"question":"Қасиетті Рим империясының мұрагері – Герман одағы ненің нәтижесінде түбегейлі таратылды?","choices":["Дат соғысы","Австрия-пруссия соғысы","Франк-пруссия соғысы"],"answer":1,"title":"Роспуск союза","steps":["В 1866 году Пруссия победила австрийские войска и добилась нового устройства немецких земель. Старый союз прекратил существовать.","Результат определила австро-прусская война."]},{"number":10,"question":"Эльзас пен Лотарингия Германияға қандай соғыстың нәтижесінде қосылды?","choices":["Бірінші дүниежүзілік соғыс","1864 жылғы Дат соғысы","1870-1871 жылғы Франк-пруссия соғысы"],"answer":2,"title":"Эльзас и Лотарингия","steps":["В 1870–1871 годах армия германских государств победила Францию. Мирный договор изменил границу.","После Франко-прусской войны к Германской империи отошли Эльзас и часть Лотарингии."]},{"number":11,"question":"Физикадан тұңғыш рет Нобель сыйлығын алған ғалым кім?","choices":["К.Ф.Браун","В.Вин","В.К.Рентген"],"answer":2,"title":"Первая премия","steps":["В 1901 году премию вручили за открытие лучей, которые проходят через мягкие ткани и оставляют изображение костей.","Первая Нобелевская премия по физике досталась Вильгельму Конраду Рентгену."]},{"number":12,"question":"Швейцария конфедерациясына алғашқылардың бірі болып қосылған қала.","choices":["Люцерн","Берн","Цюрих"],"answer":0,"title":"Расширение конфедерации","steps":["После первых трёх лесных кантонов союз стал принимать города. Люцерн присоединился в 1332 году, раньше Цюриха и Берна.","Среди предложенных городов выбираем Люцерн."]},{"number":13,"question":"ХҮІІ-ХІХ ғасырлардағы «неміс дуализмі» нелердің қарама-қарсы келуі болды?","choices":["Солтүстік пен оңтүстік","Батыс пен шығыс","Габсбургтер мен Гогенцоллерндер"],"answer":2,"title":"Две силы Германии","steps":["В споре за первенство сталкивались интересы Пруссии и Австрии. За каждой стояла своя правящая династия.","Пруссией управляли Гогенцоллерны, а Австрией — Габсбурги."]},{"number":14,"question":"Аңыз бойынша, аймақта алғаш кездестірген жануардың құрметіне герцог атын қойған қала.","choices":["Берлин","Базель","Берн"],"answer":2,"title":"Имя от зверя","steps":["По легенде, герцог назвал новую крепость в честь медведя, встреченного на охоте. Этот зверь остался на гербе города.","Так предание объясняет название Берн."]},{"number":15,"question":"Соңғы герман императоры ІІ Вильгельм қай әулетке жатты?","choices":["Гогенштауфендер","Гогенцоллерндер","Габсбургтер"],"answer":1,"title":"Последний император","steps":["Последний германский император был также королём Пруссии. Вильгельм II приходился внуком Вильгельму I.","Оба принадлежали прусской ветви династии Гогенцоллернов."]},{"number":16,"question":"Ф.Гауфтың қай ертегісінде патшаның, ханшайымның және сарай қызметкерлерінің мұрындары ұзарып, құлақтары есектің құлағындай болып кетеді?","choices":["«Ләйлек-халиф»","«Тәмпіш мұрын» (Карлик нос)","«Кішкентай Мук»"],"answer":2,"title":"Плоды и заклятие","steps":["Волшебные плоды делают уши длинными и уродуют носы придворных. Герой использует противоядие, чтобы вернуть своё имущество.","Так заканчивается сказка «Маленький Мук»."]},{"number":17,"question":"Қай ертегіде Сиқырлы әлем фарфордан жасалған болады?","choices":["«Шақпақшы» (Щелкунчик)","«Мирточка»","«Руненберг»"],"answer":1,"title":"Хрупкая страна","steps":["В сказке о девочке и необыкновенном мире хрупкие предметы и обитатели сделаны из фарфора. Фарфор служит важной деталью сюжета.","В сборниках немецких сказок этот текст называется «Мирточка»."]},{"number":18,"question":"Кемесі аударылып қалған және күшігенді жеңіп, арыстанды құтқарған қай балладаның кейіпкері?","choices":["«Линденшмидт»","«Екі ағайынды жігіт туралы баллада»","«Генрих-Арыстан туралы баллада»"],"answer":2,"title":"Спасённый лев","steps":["Лев остаётся верен своему спасителю. Связь героя со львом отразилась и в его прозвище.","Этот сюжет относится к «Балладе о Генрихе-Льве»."]},{"number":19,"question":"Су перісінің әйелі болған неміс балладаларының кейіпкері.","choices":["Лорелея","Лилофея","Теңіз сиқыршысы"],"answer":1,"title":"Жена водяного","steps":["Героиня старой немецкой баллады покидает человеческий мир, чтобы жить с водяным. Позднее она чувствует себя чужой среди людей.","Героиню называют Лилофеей."]},{"number":20,"question":"Вильгельм Телль фогттың қандай бұйрығын орындаудан бас тартты?","choices":["Бұқаларды беру","Оның қалпағына бас ию","Ұлының басына қойылған алманы атып түсіру"],"answer":1,"title":"Приказ наместника","steps":["Геслер водружает на шест головной убор, который должен заменить его присутствие. Проходящие обязаны выражать почтение.","Телль отказывается кланяться шляпе наместника."]},{"number":21,"question":"Э.Т.А.Гофманның ертегісінің желісі бойынша жазылған П.Чайковскийдің балеті.","choices":["«Шақпақшы» (Щелкунчик)","«Аққулар көлі»","«Ұйқыдағы ару»"],"answer":0,"title":"Сказка в балете","steps":["Музыка сопровождает рождественский праздник, бой игрушек с мышами и путешествие в сказочную страну сладостей.","Чайковский написал балет «Щелкунчик» по переработке сказки Гофмана."]},{"number":22,"question":"Тышқандар патшасын жеңген соң Шақпақшы (Щелкунчик) Мариға не сыйлады?","choices":["Қуыршақ","Бір қорап марципан","Жеті алтын тәж"],"answer":2,"title":"Дар после победы","steps":["У мышиного короля семь голов, и каждая увенчана короной. После победы Щелкунчик приносит Мари знаки сражения.","В подарок он отдаёт семь золотых корон."]},{"number":23,"question":"И.В.Гётенің «Рейнеке-Лис» шығармасында күш пен ақымақтықтың бейнесінде болған жануар.","choices":["Аю","Түлкі","Қасқыр"],"answer":0,"title":"Сила без хитрости","steps":["В поэме лис заманивает медведя Брюна обещанием мёда. Сильный герой попадается в ловушку из-за доверчивости.","Медведь олицетворяет силу, которой легко воспользоваться хитрецу."]},{"number":24,"question":"Ағайынды Гриммдердің ертегісінде айтылғандай, атбас бұршақтың ортасындағы қара сызық қайдан келген?","choices":["Атбас бұршақтарды балалар солай етіп бояп қойған","Бағбандар жаңа түрін өсірген","Тігінші екі жағын қара жіппен тігіп қойған"],"answer":2,"title":"Чёрный шов","steps":["Боб так сильно смеётся, что лопается. Герою помогает человек, умеющий работать иглой.","Портной сшивает половинки чёрной ниткой."]},{"number":25,"question":"Немістің балладасындағы Лорелея атты қыз су перісі жартастан қандай өзенге қарап тұрды?","choices":["Эльба","Дунай","Рейн"],"answer":2,"title":"Река у утёса","steps":["Лорелея расчёсывает волосы и поёт над опасным изгибом реки. Песня отвлекает лодочников от камней.","Утёс Лорелей находится над Рейном."]},{"number":26,"question":"Бальмунг семсерінің иесі болған көне эпостың кейіпкері.","choices":["Зигфрид","Лоэнгрин","Тангейзер"],"answer":0,"title":"Меч эпоса","steps":["Бальмунг фигурирует в «Песни о Нибелунгах». У меча сложная судьба, но в центре его истории — герой, победивший дракона.","Меч принадлежал Зигфриду."]},{"number":27,"question":"В.Гауфтың «Суық жүрек» ертегісінде, шатқалдың түбіне түсуге Петерге көмектесу үшін Михель-Алып ненің биіктігімен бірдей болып үлкейді?","choices":["Шіркеу мұнарасының","Ратушаның","Диірменнің"],"answer":0,"title":"Размер великана","steps":["Михель должен быть достаточно велик, чтобы дотянуться до дна глубокого ущелья и опустить туда Петера.","В сказке размер великана сравнивают с колокольней."]},{"number":28,"question":"В.Гауфтың ертегісіндегі кейіпкер Петер Мунк неліктен Шыны Адаммен кездеспекші болды?","choices":["Жұмыс істегенді ұнататын","Өлең шығара алатын","Жексенбі күні туған"],"answer":2,"title":"Условие встречи","steps":["Приговорка для вызова помощника упоминает день рождения просителя. Петер знает, что выполняет это условие.","Он родился в воскресенье."]},{"number":29,"question":"Дж.Крюстің «Тим Талер, немесе Сатылған күлкі» повесінде өзінің жұқпалы күлкісі үшін Тим қандай лақап атқа ие болды?","choices":["«Жарылатын»","«Қатты дауысты»","«Күлегеш»"],"answer":0,"title":"Заразительный хохот","steps":["Смех Тима начинается неожиданно и заражает других. Окружающие сравнивают такой резкий звук со взрывом.","Его прозвище — «Взрывной»."]},{"number":30,"question":"Бала кезінде шет тілдерін жақсырақ меңгеру үшін, кейіпкерлері ағылшын, француз, латын, тағы да басқа тілдерде сөйлесетін роман жазған ақын кім?","choices":["И.В.Гёте","Э.Т.А.Гофман","К.Брентано"],"answer":0,"title":"Роман на разных языках","steps":["Писатель вспоминает это упражнение в автобиографии «Поэзия и правда». Разные персонажи писали письма на разных языках.","Это рассказ Гёте о собственном детстве."]},{"number":31,"question":"Сәулетші К.Лангханс салған және Берлиннің әйгілі нышандарының біріне айналған ғимарат.","choices":["Берлин соборы","Рейхстаг ғимараты","Бранденбург қақпасы"],"answer":2,"title":"Ворота столицы","steps":["Колонны образуют несколько проходов, а наверху стоит квадрига. Автор использовал мотивы древнегреческих пропилей.","Так выглядят Бранденбургские ворота Лангханса."]},{"number":32,"question":"Жинағында миллионнан астам жәдігерлер бар, герман халқының ең ірі мәдениет тарихы мұражайы қай қалада орналасқан?","choices":["Нюрнберг","Дрезден","Мюнхен"],"answer":0,"title":"Большое музейное собрание","steps":["Германский национальный музей вырос из собрания предметов истории германоязычных земель.","Этот музей расположен в Нюрнберге."]},{"number":33,"question":"Қазып алынған құс – археоптерикс деп қандай ғалым-өнертапқыштың құрметіне аталған?","choices":["В.К.Рентген","Р.Бош","В.Сименс"],"answer":2,"title":"Ископаемая птица","steps":["Хорошо сохранившаяся окаменелость археоптерикса стала известна как берлинский экземпляр. Предприниматель помог приобрести её для научного собрания.","Имя Вернера фон Сименса использовали в названии Archaeopteryx siemensii."]},{"number":34,"question":"Мәскеудегі барон Мюнхгаузенге арналған мұражайда тұрған жәдігер.","choices":["Бірнеше тортқа арналған бір балауыз шам","Үш үлкен емен","Дыбыстар алғашында қатып қалатын, сосын барып еритін мүйіз"],"answer":2,"title":"Замёрзшие звуки","steps":["В рассказах Мюнхгаузена музыкант не может сыграть на морозе. Позже в тепле звуки будто оттаивают сами.","По сюжету они вылетают из рожка."]},{"number":35,"question":"Скрипкада ойнағанды ұнататын, Нобель сыйлығының лауреаты атанған ғалым кім?","choices":["А.Эйнштейн","Г.Ом","Г.Герц"],"answer":0,"title":"Скрипка учёного","steps":["Физик с детства учился играть на скрипке и любил Моцарта. Он продолжал играть и после научного признания.","Скрипкой увлекался Альберт Эйнштейн."]},{"number":36,"question":"ХҮІ-ХҮІІІ ғасырларда Ресей қалаларының маңынан шет жерліктерді қоныстандыру үшін арнайы бөлінген жер қалай аталды?","choices":["Неміс слободасы","Австрия слободасы","Швейцария слободасы"],"answer":0,"title":"Район иноземцев","steps":["В российских городах иностранцам могли выделять отдельное место жительства. Слово «немецкий» прежде могло относиться к иностранцам вообще.","Такой район назывался Немецкой слободой."]},{"number":37,"question":"Немістер осы жарыс түрінің көмегімен олимпиада алауын Олимпиада ойындарының астанасына жеткізуді ең алғаш ойлап тапқан. Бұл қандай жарыс?","choices":["Велосипед жарыстары","Бағдарлау","Эстафета"],"answer":2,"title":"Передача огня","steps":["Для Игр 1936 года факел доставили из Греции до Берлина. Бегуны передавали его друг другу на соседних отрезках.","Такой способ движения называется эстафетой."]},{"number":38,"question":"Габсбургтер әулетінің қамалы қазір қай жерде орналасқан?","choices":["Германия","Австрия","Швейцария"],"answer":2,"title":"Родовой замок","steps":["Замок Габсбург стоит над рекой Аре в кантоне Аргау. Позже правящая семья перенесла центр власти в Австрию.","Первоначальный замок находится в Швейцарии."]},{"number":39,"question":"Қандай таудың шыңы Германия аумағындағы ең биік нүкте болып табылады?","choices":["Гросглокнер","Цугшпитце","Дюфур"],"answer":1,"title":"Высшая вершина","steps":["На границе с Австрией в Баварских Альпах находится вершина высотой 2962 метра. Более высоких точек в Германии нет.","Это Цугшпитце."]},{"number":40,"question":"Басқару түрі конститутциялық монархия болып табылатын неміс тілді ел.","choices":["Австрия","Германия","Лихтенштейн"],"answer":2,"title":"Немецкий язык и монархия","steps":["Государство расположено между Швейцарией и Австрией. Его главу называют князем, а полномочия определяет конституция.","Это Лихтенштейн."]},{"number":41,"question":"Мюнхендегі Немістің аңшылық пен балық аулау мұражайына кіре берісте сүтқоректі мен балықтың екі қола мүсіні орналасқан. Ол ненің мүсіндері?","choices":["Бұлан мен алабұға","Аю мен шортан","Қабан мен жайын"],"answer":2,"title":"Две бронзовые фигуры","steps":["У входа показаны зверь лесов с клыками и рыба с усами. Обе фигуры напоминают о названии музея охоты и рыболовства.","Это кабан и сом."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/41.webp","alt":"Две бронзовые фигуры · 41-тапсырмаға сурет","caption":"41-тапсырмаға сурет","width":111,"height":89}},{"number":42,"question":"Айналаны тамашалайтын Хаусманнструм мұнарасы, Ағылшын баспалдағы және Саксон княздарының галереясы бар Дрездендегі көне сарай.","choices":["Пильница сарайы","Сарай-резиденция","Жапон сарайы"],"answer":1,"title":"Здание с башней","steps":["Хаусманнстурм входит в дворцовый комплекс саксонских правителей. Он стоит в старом центре рядом с придворной церковью.","Эти помещения относятся к дрезденскому Дворцу-резиденции."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/42.webp","alt":"Здание с башней · 42-тапсырмаға сурет","caption":"42-тапсырмаға сурет","width":110,"height":86}},{"number":43,"question":"Король ІІ Людвигтің жұрт көзінен жасырыну үшін салғызған қамалы.","choices":["Хоэншвангау","Берг","Нойшванштайн"],"answer":2,"title":"Уединённый замок","steps":["Людвиг II хотел жить вдали от двора. Он заказал высокий белый замок в горах с интерьерами по мотивам легенд.","Мечта короля воплотилась в Нойшванштайне."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/43.webp","alt":"Уединённый замок · 43-тапсырмаға сурет","caption":"43-тапсырмаға сурет","width":111,"height":87}},{"number":44,"question":"Осы саясаткердің құрметіне ХІХ-ХХ ғасырларда әр түрлі елдерде көптеген мұнаралар бой көтерді. Бұл саясаткер кім?","choices":["І Франц Иосиф","К.фон Меттерних","О.фон Бисмарк"],"answer":2,"title":"Башни в разных странах","steps":["Многие башни построили после смерти политика, связанного с объединением Германии. На некоторых наверху зажигали огонь.","Эти памятники называют башнями Бисмарка."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/44.webp","alt":"Башни в разных странах · 44-тапсырмаға сурет","caption":"44-тапсырмаға сурет","width":110,"height":87}},{"number":45,"question":"1880-1884 жылдары әлемдегі ең биік ғимарат деп саналған неміс соборы.","choices":["Фрайбург соборы","Ульм соборы","Кёльн соборы"],"answer":2,"title":"Собор с двумя шпилями","steps":["Две западные башни завершили в 1880 году. Их высота около 157 метров сделала собор рекордсменом на несколько лет.","Это Кёльнский собор."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/45.webp","alt":"Собор с двумя шпилями · 45-тапсырмаға сурет","caption":"45-тапсырмаға сурет","width":110,"height":88}},{"number":46,"question":"Осы қаланың базар алаңында орнатылған готикалық су бұрқақ қырық мүсінмен безендірілген, оның ішінде король Артурдың және император Ұлы Карлдың да мүсіндері бар. Бұл қай қала?","choices":["Аусбург","Нюрнберг","Бамберг"],"answer":1,"title":"Фонтан на рынке","steps":["Каменные фигуры королей, пророков и героев размещены по ярусам готического фонтана. Сам фонтан стоит на Главном рынке.","Фигуры короля Артура и Карла Великого украшают фонтан Нюрнберга."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/46.webp","alt":"Фонтан на рынке · 46-тапсырмаға сурет","caption":"46-тапсырмаға сурет","width":119,"height":93}},{"number":47,"question":"Иллюстрацияда көрсетіліп отырған Петергофтағы православ шіркеуінің жобасының авторы, неміс сәулетшісі кім?","choices":["Л.фон Кленце","П.Беренс","К.Ф.Шинкель"],"answer":2,"title":"Часовня в парке","steps":["В петергофской Александрии находится православная церковь в виде готической капеллы. Её металлический декор похож на средневековую архитектуру.","Проект капеллы подготовил Карл Фридрих Шинкель."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/47.webp","alt":"Часовня в парке · 47-тапсырмаға сурет","caption":"47-тапсырмаға сурет","width":119,"height":96}},{"number":48,"question":"Германияда зауыт жұмыскерлерінің еңбегін өз суреттерінде бірінші боп бейнелеген, берілген суреттің авторы кім?","choices":["В.фон Каульбах","А.Менцель","Ф.Ленбах"],"answer":1,"title":"Работа у печи","steps":["На зарисовке из прокатного цеха заметны колесо, печь и люди за работой. Художник наблюдал за рабочими, прежде чем написать большую картину.","Этюд и полотно о железопрокатном заводе создал Адольф Менцель."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/48.webp","alt":"Работа у печи · 48-тапсырмаға сурет","caption":"48-тапсырмаға сурет","detailSrc":"assets/golden-fleece/2013/interactive-5-6-kz/48-detail.webp","width":484,"height":620}},{"number":49,"question":"Германия тарихы мен мәдениетіндегі көрнекті тұлғаларға арналған Атақ Залы – Вальхалланы салған неміс сәулетшісі кім?","choices":["П.Беренс","К.Ф.Шинкель","Л.фон Кленце"],"answer":2,"title":"Храм славы","steps":["Возведённая по заказу Людвига I Вальхалла напоминает античный храм над Дунаем. Тот же архитектор проектировал музейные здания Мюнхена.","Архитектора звали Лео фон Кленце."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/49.webp","alt":"Храм славы · 49-тапсырмаға сурет","caption":"49-тапсырмаға сурет","width":119,"height":93}},{"number":50,"question":"Марбургтегі Әулие Елизавета шіркеуі қандай стильде салынған сәулет өнері ескерткішіне жатады?","choices":["Романдық","Готикалық","Барокко"],"answer":1,"title":"Стиль церкви","steps":["Стрельчатые арки, высокие симметричные башни и вертикальные членения подсказывают средневековый стиль.","Церковь Святой Елизаветы в Марбурге построена в готическом стиле."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/50.webp","alt":"Стиль церкви · 50-тапсырмаға сурет","caption":"50-тапсырмаға сурет","width":131,"height":105}},{"number":51,"question":"Мына берілген суреттің авторы, барлығы әдемі табиғат көрінісіне құштар деген ұғымды ұстана отыра, негізгі салатын нәрсесін немесе адамын табиғат аясында жиі бейнелеген. Бұл кім?","choices":["Ф.О.Рунге","К.Ф.Шинкель","Ф.В.фон Шадов"],"answer":0,"title":"Человек в пейзаже","steps":["В портретах немецкого романтика растения и вид за спиной героя помогают показать характер и настроение. Он также разработал учение о цвете.","Так соединял фигуры и природу Филипп Отто Рунге."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/51.webp","alt":"Человек в пейзаже · 51-тапсырмаға сурет","caption":"51-тапсырмаға сурет","width":115,"height":85}},{"number":52,"question":"А.Дюрер өзінің туған қаласы Нюрнбергке сыйға тартқан сурет қалай аталады?","choices":["«Таспиқ мерекесі»","«Төрт апостол»","«Төрт салт атты»"],"answer":1,"title":"Городской дар художника","steps":["На двух вертикальных панелях изображены четыре фигуры в полный рост. Их сопровождают книги и надписи.","Дюрер подарил городу «Четырёх апостолов»."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/52.webp","alt":"Городской дар художника · 52-тапсырмаға сурет","caption":"52-тапсырмаға сурет","width":84,"height":118}},{"number":53,"question":"Бұл сарай кешені сәулетші Б.Нейманның жобасы бойынша салынған, ал ішкі бөлмелерін безендіруге Дж.Тьеполо қатысқан. Бұл қандай сарай?","choices":["Шёнбрунн","Вюрцбург резиденциясы","Хофбург"],"answer":1,"title":"Лестница и фреска","steps":["Балтазар Нейман устроил широкий лестничный зал, а Тьеполо расписал его потолок. Ансамбль создавался для князей-епископов.","Это Вюрцбургская резиденция."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/53.webp","alt":"Лестница и фреска · 53-тапсырмаға сурет","caption":"53-тапсырмаға сурет","width":119,"height":94}},{"number":54,"question":"Басында жеке меншік ғибадатхана ретінде салынып, кейін тұрғындардың ықпалымен барлық жұрт кіре алатын болған мюнхен шіркеуі.","choices":["Әулие Михаил шіркеуі","Әулие Ана құдайдың соборы","Әулие Иоанн Непомуктың шіркеуі"],"answer":2,"title":"Частная церковь","steps":["Братья Азам построили небольшой барочный храм рядом со своим домом. Горожане получили возможность посещать церковь.","Мюнхенский храм посвящён святому Иоанну Непомуку."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/54.webp","alt":"Частная церковь · 54-тапсырмаға сурет","caption":"54-тапсырмаға сурет","width":117,"height":91}},{"number":55,"question":"Мына беріліп отырған суреттің авторы пейзаждарында, табиғатты пайымдап қарау әсерін күшейте отыра, адамдарды көрермендерге арқасымен беріп бейнелеген. Бұл қандай суретші?","choices":["К.Д.Фридрих","М.Либерман","А.Альтдорфер"],"answer":0,"title":"Фигура спиной","steps":["Художник помещает зрителя позади героя, который смотрит на природу. Мы видим тот же пейзаж, что и человек на полотне.","Этот приём часто использовал Каспар Давид Фридрих."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/55.webp","alt":"Фигура спиной · 55-тапсырмаға сурет","caption":"55-тапсырмаға сурет","width":92,"height":118}},{"number":56,"question":"Ең алғашқы автопортретін 13 жасында салған суретші кім?","choices":["Кіші Г.Гольбейн","А.Дюрер","Үлкен Л.Кранах"],"answer":1,"title":"Ранний автопортрет","steps":["Сохранился рисунок мальчика серебряным штифтом. Надпись сообщает, что автор изобразил себя перед зеркалом в тринадцать лет.","Это ранний автопортрет Альбрехта Дюрера."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/56.webp","alt":"Ранний автопортрет · 56-тапсырмаға сурет","caption":"56-тапсырмаға сурет","detailSrc":"assets/golden-fleece/2013/interactive-5-6-kz/56-detail.webp","width":434,"height":620}},{"number":57,"question":"Мына берілген суреттің авторы М.Лютермен және оның отбасымен достық қарым-қатынаста болған. Бұл қай суретші?","choices":["Кіші Г.Гольбейн","А.Дюрер","Үлкен Л.Кранах"],"answer":2,"title":"Портрет реформатора","steps":["Художник из Виттенберга написал много портретов Мартина Лютера и его жены. Они помогли распространить узнаваемое лицо реформатора.","Близким знакомым Лютера был Лукас Кранах Старший."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/57.webp","alt":"Портрет реформатора · 57-тапсырмаға сурет","caption":"57-тапсырмаға сурет","width":79,"height":118}},{"number":58,"question":"Мына берілген туындының авторы 900-ден артық суреттерді өмірге әкелген, олардың ішінде «штудилер» деп аталған жинақ, яғни жануарлар мен өсімдіктердің натуралистік бейнелері салынған суреттер де бар. Бұл қандай суретші?","choices":["Үлкен Л.Кранах","А.Дюрер","Үлкен Г.Гольбейн"],"answer":1,"title":"Рисунки с натуры","steps":["Животные и растения на штудиях изображены особенно внимательно. Среди известных образцов — «Молодой заяц» и «Большой кусок луга».","Эти работы сделал Альбрехт Дюрер."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/58.webp","alt":"Рисунки с натуры · 58-тапсырмаға сурет","caption":"58-тапсырмаға сурет","width":84,"height":118}},{"number":59,"question":"Мына берілген суреттің авторы Эразм Роттердамскиймен таныс болған және оның бірнеше портретін салған. Бұл суретші кім?","choices":["А.Дюрер","Үлкен Л.Кранах","Кіші Г.Гольбейн"],"answer":2,"title":"Портрет гуманиста","steps":["На портретах Эразм часто показан за работой, с книгами и письмом. Художник познакомился с ним в Базеле.","Несколько портретов Эразма создал Ганс Гольбейн Младший."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/59.webp","alt":"Портрет гуманиста · 59-тапсырмаға сурет","caption":"59-тапсырмаға сурет","width":84,"height":118}},{"number":60,"question":"Мына берілген суреттің авторы, Лондондағы Корольдік Көркемсурет академиясының негізін қалаушылардың бірі болған кім?","choices":["А.Кауфман","Р.Менгс","В.фон Каульбах"],"answer":0,"title":"Лондонская академия","steps":["Швейцарская художница жила в Лондоне и писала портреты и исторические сцены. В 1768 году вошла в состав учредителей Королевской академии.","Это Ангелика Кауфман."],"figure":{"src":"assets/golden-fleece/2013/interactive-5-6-kz/60.webp","alt":"Лондонская академия · 60-тапсырмаға сурет","caption":"60-тапсырмаға сурет","width":115,"height":88}}]);
